targets.query:
// dns_filter_list.matches is already a per-minute delta, so summing
// over the window is the number of blocked lookups in it.
from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "dns_filter_list" and r._field == "matches")
  |> aggregateWindow(every: v.windowPeriod, fn: sum, createEmpty: false)
  |> group(columns: ["category"])
  |> aggregateWindow(every: v.windowPeriod, fn: sum, createEmpty: false)
  |> keep(columns: ["_time", "_value", "category"])

// `detail` carries the note; the action and category are tags, so no
// pivot is needed to get one row per change.
from(bucket: "network_traffic")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "dns_filter_control" and r._field == "detail")
  |> keep(columns: ["_time", "action", "category", "_value"])
  |> group()
  |> sort(columns: ["_time"], desc: true)
  |> limit(n: 200)
